// Get input - handle both direct JSON and webhook body
const rawInput = $input.first().json;
const input = rawInput.body || rawInput;
const errors = [];

// Sanitize string fields - trim whitespace and normalize
const stringFields = ['address', 'city', 'state', 'zip', 'propertyType', 'repairScope', 'source', 'driveLink'];
for (const field of stringFields) {
  if (typeof input[field] === 'string') {
    input[field] = input[field].trim();
  }
}

// Uppercase state (e.g. 'oh' -> 'OH')
if (typeof input.state === 'string') {
  input.state = input.state.toUpperCase();
}

// Required fields
const required = ['address', 'city', 'state', 'zip', 'askingPrice', 'arv', 'repairEstimate', 'repairScope', 'propertyType', 'source'];
for (const field of required) {
  if (!input[field] && input[field] !== 0) {
    errors.push('Missing required field: ' + field);
  }
}

// Type validations
if (input.askingPrice && input.askingPrice <= 0) errors.push('askingPrice must be > 0');
if (input.arv && input.askingPrice && input.arv <= input.askingPrice) errors.push('arv must be > askingPrice');
if (input.repairEstimate && input.repairEstimate < 0) errors.push('repairEstimate must be >= 0');

const validPropertyTypes = ['SFR', 'Duplex', 'Multi', 'Land', 'Commercial'];
if (input.propertyType && !validPropertyTypes.includes(input.propertyType)) {
  errors.push('propertyType must be one of: ' + validPropertyTypes.join(', '));
}

const validScopes = ['Light', 'Medium', 'Heavy', 'Gut'];
if (input.repairScope && !validScopes.includes(input.repairScope)) {
  errors.push('repairScope must be one of: ' + validScopes.join(', '));
}

if (errors.length > 0) {
  return [{json: {valid: false, errors}}];
}

return [{json: {valid: true, deal: input}}];

const deal = $input.first().json.deal;

function normalizeAddress(addr) {
  var normalized = addr.toLowerCase().trim();

  // Standardize street suffixes
  var replacements = {
    ' st ': ' street ', ' st$': ' street',
    ' ave ': ' avenue ', ' ave$': ' avenue',
    ' dr ': ' drive ', ' dr$': ' drive',
    ' rd ': ' road ', ' rd$': ' road',
    ' blvd ': ' boulevard ', ' blvd$': ' boulevard',
    ' ln ': ' lane ', ' ln$': ' lane',
    ' ct ': ' court ', ' ct$': ' court',
    ' cir ': ' circle ', ' cir$': ' circle',
    ' pl ': ' place ', ' pl$': ' place'
  };

  for (var abbr in replacements) {
    normalized = normalized.replace(new RegExp(abbr, 'g'), replacements[abbr]);
  }

  // Remove punctuation
  normalized = normalized.replace(/[.,#]/g, '');

  // Remove unit/apt/suite
  normalized = normalized.replace(/\s+(apt|unit|suite|ste|#)\s*\S*/gi, '');

  // Collapse whitespace
  normalized = normalized.replace(/\s+/g, ' ').trim();

  return normalized;
}

var addressNormalized = normalizeAddress(deal.address);

return [{json: {...deal, addressNormalized: addressNormalized}}];

var deal = $input.first().json;

// Calculate margin
var margin = ((deal.arv - deal.askingPrice - deal.repairEstimate) / deal.arv) * 100;

// Helper function
function clamp(value, min, max) {
  return Math.min(Math.max(value, min), max);
}

// Score components
var marginScore = clamp(margin / 40 * 100, 0, 100);
var demandScore = 50; // Default

var conditionScores = { Light: 90, Medium: 70, Heavy: 40, Gut: 20 };
var conditionScore = conditionScores[deal.repairScope] || 50;

var compConfidence = deal.compConfidence || 'Medium';
var compScores = { High: 100, Medium: 60, Low: 30 };
var compScore = compScores[compConfidence] || 60;

var domScore = 70;
var titleScore = 100;

// Calculate overall deal score
var dealScore = Math.round(
  marginScore * 0.30 +
  demandScore * 0.20 +
  domScore * 0.15 +
  conditionScore * 0.15 +
  compScore * 0.10 +
  titleScore * 0.10
);

// Determine best strategy
var bestStrategy;
if (margin >= 25 && ['Light', 'Medium'].indexOf(deal.repairScope) !== -1) {
  bestStrategy = 'Flip';
} else if (margin >= 20 && ['Medium', 'Heavy'].indexOf(deal.repairScope) !== -1) {
  bestStrategy = 'BRRRR';
} else if (margin >= 15) {
  bestStrategy = 'Rental';
} else {
  bestStrategy = 'Wholesale';
}

return [{json: {
  ...deal,
  margin: Math.round(margin * 10) / 10,
  dealScore: dealScore,
  bestStrategy: bestStrategy,
  compConfidence: compConfidence
}}];
